@model Umbraco.Bench.Umbraco.Models.Blocks.HeroModel
<section class="relative rounded-3xl overflow-hidden bg-slate-900 border border-slate-800">
    @if (!string.IsNullOrEmpty(Model.ImageUrl))
    {
        <img src="@Model.ImageUrl" alt="" class="absolute inset-0 h-full w-full object-cover opacity-30" />
    }
    <div class="relative px-8 py-20 sm:px-16 sm:py-28">
        <h1 class="text-4xl sm:text-6xl font-bold tracking-tight text-white">@Model.Heading</h1>
        @if (!string.IsNullOrEmpty(Model.Subheading))
        {
            <p class="mt-6 max-w-2xl text-lg text-slate-300">@Model.Subheading</p>
        }
    </div>
</section>

